import subprocess
import sys
from pathlib import Path
from app import parse_numbers

Path('.app.py.before').write_bytes(Path('app.py').read_bytes())
for text in ['', '1,,2', ',1', '1,', '1_000', '\\u0661\\u0662', '1.5', '1e3', 'nope']:
    try:
        actual = parse_numbers(text)
    except ValueError:
        print(f'parser {text"'!r}: correctly rejected'"')
    else:
        print(f'parser {text"'!r}: DEFECT accepted {actual!r}'"')
large = '9' * 5000
try:
    result = parse_numbers(large)
except ValueError:
    print('parser 5000-digit integer: DEFECT rejected')
else:
    print('parser 5000-digit integer: accepted')
for args in [['1,-2,+3'], ['-2,-3'], [], ['1', '2'], ['1,,2'], ['abc'], [large]]:
    result = subprocess.run([sys.executable, '-B', 'app.py', *args], capture_output=True, text=True)
    label = '5000-digit integer' if args == [large] else repr(args)
    print(f'CLI {label}: exit={result.returncode}; stdout={result.stdout[:80]"'!r}; stderr={bool(result.stderr)}; traceback={"Traceback" in result.stderr}'"')
